import{_ as t,o as a,c as r,aF as o}from"./chunks/framework.CNkxH4QO.js";const u=JSON.parse('{"title":"krawler-centipede","description":"A Krawler based service to get the antennas status of the RTK Centipede Network","frontmatter":{"title":"krawler-centipede","description":"A Krawler based service to get the antennas status of the RTK Centipede Network"},"headers":[],"relativePath":"packages/krawler-centipede/index.md","filePath":"packages/krawler-centipede/index.md"}'),d={name:"packages/krawler-centipede/index.md"};function n(i,e,s,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler-centipede" tabindex="-1">krawler-centipede <a class="header-anchor" href="#krawler-centipede" aria-label="Permalink to &quot;krawler-centipede&quot;">​</a></h1><p><em>A Krawler based service to get the antennas status of the RTK Centipede Network</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-centipede</strong> job allow to scrape antennas status from the <a href="https://centipede.fr/" target="_blank" rel="noreferrer">centipede RTK server</a>. The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in 2 collections:</p><ul><li>the <code>bases</code> collection stores the data relative to the bases</li><li>the <code>pings</code> collection stores the ping status of each base</li></ul><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The job is executed according a specific cron expression. By default, every 5 minutes.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>DB_URL</code></td><td>The mongoDB database URL. The default value is <code>mongodb://127.0.0.1:27017/centipede</code></td></tr><tr><td><code>TTL</code></td><td>The measurements data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table>',9)])])}const f=t(d,[["render",n]]);export{u as __pageData,f as default};
